import { useState } from "react";
import axios from "axios";

const symptomFlow = [
  "fever",
  "cough",
  "headache",
  "stomach_pain",
  "fatigue"
];

function SymptomChat() {
  const [currentStep, setCurrentStep] = useState(0);
  const [answers, setAnswers] = useState([]);
  const [otherSymptoms, setOtherSymptoms] = useState("");
  const [result, setResult] = useState(null);

  const answerYes = () => {
    setAnswers([...answers, symptomFlow[currentStep]]);
    setCurrentStep(currentStep + 1);
  };

  const answerNo = () => {
    setCurrentStep(currentStep + 1);
  };

  const submit = async () => {
    const extra = otherSymptoms.split(",").map(s => s.trim());
    const finalSymptoms = [...answers, ...extra];

    const res = await axios.post("http://127.0.0.1:5000/predict", {
      symptoms: finalSymptoms
    });

    setResult(res.data);
  };

  return (
    <div style={{padding:"30px"}}>
      <h2>AI Health Assistant</h2>

      {!result && currentStep < symptomFlow.length && (
        <div>
          <h3>Do you have {symptomFlow[currentStep]}?</h3>
          <button onClick={answerYes}>Yes</button>
          <button onClick={answerNo}>No</button>
        </div>
      )}

      {currentStep >= symptomFlow.length && !result && (
        <div>
          <h3>Any other symptoms? (comma separated)</h3>
          <input onChange={e=>setOtherSymptoms(e.target.value)} />
          <br /><br />
          <button onClick={submit}>Submit</button>
        </div>
      )}

      {result && (
        <div>
          <h2>Disease: {result.disease}</h2>
          <h2>Urgency: {result.urgency}</h2>
          <h2>Confidence: {result.confidence}%</h2>
        </div>
      )}
    </div>
  );
}

export default SymptomChat;
